@GameTestHolder("tncjourney") @PrefixGameTestTemplate(false)
public final class JourneyGameTests {
    @GameTest(template="building_test_empty",timeoutTicks=50) public static void allActualPotionIngredientsAndCommissionTargetsExist(GameTestHelper h){for(var e:Elixir.values())for(String id:e.ingredients)h.assertTrue(net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(ResourceLocation.parse(id))!=null&&net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(ResourceLocation.parse(id))!=Items.AIR,"Ingredient exists "+id);h.assertTrue(CommissionCatalog.all().size()==10,"Ten actual reloadable offers");for(var o:CommissionCatalog.all())if(o.kind().equals("kill"))h.assertTrue(net.minecraftforge.registries.ForgeRegistries.ENTITY_TYPES.containsKey(ResourceLocation.parse(o.target())),"Target exists "+o.target());h.succeed();}
    private static AlchemyEntity cauldron(GameTestHelper h){var pos=h.absolutePos(new BlockPos(2,2,2));h.getLevel().setBlock(pos,AlchemyContent.CAULDRON.defaultBlockState(),3);return (AlchemyEntity)h.getLevel().getBlockEntity(pos);}
    private static void fill(AlchemyEntity be,Elixir recipe){for(int i=0;i<3;i++)be.inventory.setItem(i,new ItemStack(net.minecraftforge.registries.ForgeRegistries.ITEMS.getValue(ResourceLocation.parse(recipe.ingredients.get(i))),2));be.inventory.setItem(4,new ItemStack(AlchemyContent.FUEL,2));be.inventory.setItem(5,new ItemStack(Items.GLASS_BOTTLE,2));be.fire=2;}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void alchemyConsumesExactInputsAndPausesAtBlockedOutput(GameTestHelper h){var be=cauldron(h);fill(be,Elixir.SPRING);be.inventory.setItem(6,new ItemStack(Items.STONE,64));for(int i=0;i<300;i++)AlchemyEntity.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);h.assertTrue(be.progress==0&&be.inventory.getItem(4).getCount()==2&&be.inventory.getItem(0).getCount()==2,"blocked output never spends ingredients or fuel");be.inventory.setItem(6,ItemStack.EMPTY);for(int i=0;i<Elixir.SPRING.ticks;i++)AlchemyEntity.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);h.assertTrue(be.inventory.getItem(6).is(AlchemyContent.POTIONS.get(Elixir.SPRING))&&be.inventory.getItem(6).getCount()==1&&be.inventory.getItem(0).getCount()==1&&be.inventory.getItem(5).getCount()==1,"one batch consumes one of each herb and bottle");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void cauldronSaveAndSurvivalDropPreserveOneInventory(GameTestHelper h){var be=cauldron(h);fill(be,Elixir.BLOOM);for(int i=0;i<80;i++)AlchemyEntity.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);var saved=be.saveWithoutMetadata();var restored=new AlchemyEntity(be.getBlockPos(),be.getBlockState());restored.load(saved);h.assertTrue(restored.progress==80&&restored.burn==be.burn&&restored.inventory.getItem(0).getCount()==2,"restart preserves exact progress and inputs");var drops=Block.getDrops(be.getBlockState(),h.getLevel(),be.getBlockPos(),be);h.assertTrue(drops.size()==1&&drops.get(0).is(AlchemyContent.CAULDRON.asItem()),"one packed cauldron drop");var packed=drops.get(0).getTagElement("BlockEntityTag");h.assertTrue(packed!=null&&packed.getInt("Progress")==80&&!packed.getList("Items",10).isEmpty(),"packed loot keeps progress and inventory");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=30) public static void preparationStorageIsPrivateAndSipCannotOverwriteAnOpenMenu(GameTestHelper h){var p=AdventureGameTests.player(h);var q=AdventureGameTests.player(h);var st=new Preparation.Storage(p);st.setItem(27,new ItemStack(AlchemyContent.POTIONS.get(Elixir.BLOOM),2));p.containerMenu=new PreparationMenu(11,p.getInventory(),st,1);p.setHealth(2);Preparation.sip(p);h.assertTrue(new Preparation.Storage(p).getItem(27).getCount()==2&&p.getHealth()==2,"open menu packet cannot consume via stale copy");p.containerMenu=p.inventoryMenu;Preparation.sip(p);h.assertTrue(new Preparation.Storage(p).getItem(27).getCount()==1&&p.getHealth()==10,"one actual carried potion consumed");Preparation.sip(p);h.assertTrue(new Preparation.Storage(p).getItem(27).getCount()==1,"shared cooldown prevents duplicate use");h.assertTrue(new Preparation.Storage(q).getItem(27).isEmpty(),"another player's storage is empty");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=30) public static void commissioningCountsKeepLegacyProgressAcrossMigration(GameTestHelper h){var old=new CompoundTag();old.putInt("NativeBounties",7);var profile=AdventureSavedData.readProfile(old);profile.recordCommission();h.assertTrue(profile.commissions()==8&&profile.reputation()==5,"old seven paper jobs plus one electronic job");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void realBoardAcceptProgressClaimAndDuplicateAreAuthoritative(GameTestHelper h)throws Exception{
        var world=h.getLevel().getServer().overworld();var store=world.getDataStorage();var old=com.tnc.tnc.world.SkyIslandSavedData.get(world);var load=old.getClass().getDeclaredMethod("load",CompoundTag.class);load.setAccessible(true);var pos=h.absolutePos(new BlockPos(4,2,4));var t=old.save(new CompoundTag());var origin=pos.subtract(com.tnc.tnc.tavern.TavernUpgrade.BOARD);t.putString("Phase","COMPLETE");t.putBoolean("LayoutReady",true);t.putInt("OriginX",origin.getX());t.putInt("OriginY",origin.getY());t.putInt("OriginZ",origin.getZ());store.set("tnc_sky_island_v5",(net.minecraft.world.level.saveddata.SavedData)load.invoke(null,t));
        try{var p=AdventureGameTests.player(h);p.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+.5);AdventureService.register(p);CommissionService.act(p,"accept","tnc:road_watch");CommissionService.act(p,"accept","tnc:road_watch");var record=CommissionService.ledger(p).getCompound("tnc:road_watch");h.assertTrue(record.getBoolean("Active")&&record.getInt("Progress")==0,"board accepts exactly one job");CommissionService.progress(p,"kill","minecraft:spider");h.assertTrue(record.getInt("Progress")==0,"wrong target not counted");for(int i=0;i<10;i++)CommissionService.progress(p,"kill","minecraft:zombie");h.assertTrue(record.getInt("Progress")==6,"goal capped");CommissionService.act(p,"claim","tnc:road_watch");CommissionService.act(p,"claim","tnc:road_watch");h.assertTrue(AdventureService.profile(p).coins()==75&&AdventureService.profile(p).commissions()==1&&AdventureService.profile(p).hasMilestone("first_contract")&&AdventureService.profile(p).hasMilestone("bounties_1"),"one reward and existing FTB advancements");CommissionService.act(p,"accept","tnc:road_watch");h.assertTrue(!record.getBoolean("Active"),"real-time repeat cooldown");var removed=new CompoundTag();removed.putBoolean("Active",true);removed.putInt("Goal",3);CommissionService.ledger(p).put("removed:old_offer",removed);h.assertTrue(CommissionService.snapshot(p).getList("Cards",10).stream().map(n->(CompoundTag)n).anyMatch(n->n.getString("Id").equals("removed:old_offer")&&n.getBoolean("Unavailable")),"removed data-pack offer stays visible");CommissionService.act(p,"abandon","removed:old_offer");h.assertTrue(!removed.getBoolean("Active"),"removed offer can be abandoned without catalog entry");}finally{store.set("tnc_sky_island_v5",old);}h.succeed();
    }
    @GameTest(template="building_test_empty",timeoutTicks=30) public static void actualMcaInitializationNameAndMarriageChecks(GameTestHelper h)throws Exception{h.assertTrue(com.tnc.tnc.home.McaResidents.available(),"Run this suite with actual MCA");var p=AdventureGameTests.player(h);var before=p.position();FamilyLife.initialize(p);var saved=FamilyLife.mca(p);h.assertTrue((Boolean)saved.getClass().getMethod("isEntityDataSet").invoke(saved)&&p.position().equals(before),"MCA initialized without teleport");h.assertTrue(FamilyLife.partner(p)==null,"single NIL UUID is not a spouse");FamilyLife.name(p,"远行者");h.assertTrue(p.getDisplayName().getString().contains("远行者"),"role name changes visible display");h.succeed();}
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void actualMarriedSpouseAndChildUseHomeMealAndCooldown(GameTestHelper h)throws Exception {
        var p=AdventureGameTests.player(h);FamilyLife.initialize(p);var pos=h.absolutePos(new BlockPos(3,2,3));p.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+.5);
        var npc=com.tnc.tnc.home.McaResidents.create(h.getLevel(),com.tnc.tnc.home.ResidentService.ALL.get(1),pos,UUID.randomUUID());npc.setNoAi(true);h.getLevel().addFreshEntity(npc);
        var state=Class.forName("forge.net.mca.entity.ai.relationship.RelationshipState");var node=FamilyLife.entry(p);var mca=FamilyLife.mca(p);mca.getClass().getMethod("marry",net.minecraft.world.entity.Entity.class).invoke(mca,npc);
        h.assertTrue(npc.getUUID().equals(FamilyLife.partner(p)),"actual MCA marriage is observed");node.getClass().getMethod("setRelationshipState",state).invoke(node,state.getField("ENGAGED").get(null));h.assertTrue(FamilyLife.partner(p)==null,"engagement cannot unlock married content");mca.getClass().getMethod("marry",net.minecraft.world.entity.Entity.class).invoke(mca,npc);
        com.tnc.tnc.home.McaResidents.setHome(npc,pos);h.assertTrue(FamilyLife.home(p,npc),"native MCA home is recognized");var child=com.tnc.tnc.home.McaResidents.create(h.getLevel(),com.tnc.tnc.home.ResidentService.ALL.get(2),pos.north(),UUID.randomUUID());child.setAge(-24000);child.setNoAi(true);h.getLevel().addFreshEntity(child);node.getClass().getMethod("addChild",UUID.class).invoke(node,child.getUUID());h.assertTrue(FamilyLife.children(p)==1&&FamilyLife.presentChildren(p)==1,"actual nearby family child is observed");child.discard();h.assertTrue(FamilyLife.presentChildren(p)==0,"unloaded or departed child cannot speak from the family tree");
        FamilyLife.notice(p,"depart");h.assertTrue(JourneyData.get(p.server).player(p.getUUID()).getBoolean("Family_depart"),"departure waits for real married partner");p.getInventory().clearContent();p.getInventory().setItem(0,new ItemStack(Items.MUSHROOM_STEW));p.getInventory().setItem(1,new ItemStack(Items.MUSHROOM_STEW));p.getFoodData().setFoodLevel(0);FamilyLife.dinner(p);FamilyLife.dinner(p);h.assertTrue(p.getInventory().countItem(Items.BOWL)==2&&p.getInventory().countItem(Items.MUSHROOM_STEW)==0&&p.getFoodData().getFoodLevel()==8,"two separate soup bowls eaten once; both bowls returned");var record=JourneyData.get(p.server).player(p.getUUID());record.putBoolean("WelcomeShown",true);record.putInt("Away",1000);FamilyLife.tickPlayer(p);h.assertTrue(record.getInt("Away")==0&&!record.getBoolean("Family_miss"),"short return ends the absence clock");FamilyLife.notice(p,"death");p.setHealth(0);FamilyLife.tickPlayer(p);h.assertTrue(record.getBoolean("Family_death"),"death screen cannot consume home greeting");p.setHealth(10);npc.discard();h.succeed();
    }
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void dismantlingAndReplacementCannotLeaveAnOldAlchemyMenuValid(GameTestHelper h){
        var be=cauldron(h);fill(be,Elixir.BLOOM);var p=AdventureGameTests.player(h);p.setPos(be.getBlockPos().getX()+.5,be.getBlockPos().getY()+1,be.getBlockPos().getZ()+.5);var menu=new AlchemyMenu(12,p.getInventory(),be);h.assertTrue(menu.stillValid(p),"bound menu starts valid");h.assertTrue(!be.getBlockState().requiresCorrectToolForDrops()&&p.hasCorrectToolForDrops(be.getBlockState()),"survival can harvest a packed cauldron with any tool");var pos=be.getBlockPos();h.getLevel().setBlock(pos,Blocks.AIR.defaultBlockState(),3);h.getLevel().setBlock(pos,AlchemyContent.CAULDRON.defaultBlockState(),3);h.assertTrue(!menu.stillValid(p),"replacement block cannot authorize stale inventory");h.succeed();
    }
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void preparationBindsShownSegmentAndPartyMembership(GameTestHelper h){
        var p=AdventureGameTests.player(h);var d=com.tnc.tnc.dungeon.DungeonData.get(p.server);var r=new com.tnc.tnc.dungeon.DungeonData.Run(UUID.randomUUID(),p.getUUID(),177,91,com.tnc.tnc.dungeon.DungeonTheme.ASTRAL);d.runs.put(r.id,r);d.profile(p.getUUID()).putUUID("Run",r.id);var pos=com.tnc.tnc.dungeon.DungeonRealm.lobby(r).above();p.teleportTo(p.server.getLevel(com.tnc.tnc.dungeon.DungeonRealm.KEY),pos.getX()+.5,pos.getY(),pos.getZ()+.5,0,0);var menu=new PreparationMenu(12,p.getInventory(),new Preparation.Storage(p),1);h.assertTrue(menu.stillValid(p),"first segment menu valid");var t=JourneyData.get(p.server).player(p.getUUID());t.putUUID("WantedRun",r.id);t.putInt("WantedFloor",6);h.assertTrue(!menu.stillValid(p),"old displayed segment invalid after leader changes selection");Preparation.ready(p,1);h.assertTrue(!Preparation.ready(p,r,6),"old confirm does not authorize new segment");Preparation.ready(p,6);h.assertTrue(Preparation.ready(p,r,6),"matching displayed segment can confirm");r.members.add(UUID.randomUUID());h.assertTrue(!Preparation.ready(p,r,6),"party change invalidates confirmation");Preparation.clearReady(p);r.closed=true;h.succeed();
    }
    @GameTest(template="building_test_empty",timeoutTicks=40) public static void hiddenCacheRequiresSightAndNeverConsumesFullBagEntitlement(GameTestHelper h){
        var p=AdventureGameTests.player(h);var d=com.tnc.tnc.dungeon.DungeonData.get(p.server);var r=new com.tnc.tnc.dungeon.DungeonData.Run(UUID.randomUUID(),p.getUUID(),178,92,com.tnc.tnc.dungeon.DungeonTheme.ASTRAL);r.floor=1;r.state().built=true;r.state().cleared=255;d.runs.put(r.id,r);var record=d.profile(p.getUUID());record.putUUID("Run",r.id);record.putUUID("CursorRun",r.id);record.putInt("LastFloor",1);var room=r.graph().rooms.get(0);record.putInt("LastRoom",room.id());var pos=com.tnc.tnc.dungeon.DungeonRealm.center(r,room).offset(2,1,2);var level=p.server.getLevel(com.tnc.tnc.dungeon.DungeonRealm.KEY);p.teleportTo(level,pos.getX()+.5,pos.getY()+1,pos.getZ()+.5,0,0);com.tnc.tnc.dungeon.DungeonRealm.write(()->level.setBlock(pos,AlchemyContent.HIDDEN_CACHE.defaultBlockState(),3));var state=level.getBlockState(pos);var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos),Direction.UP,pos,false);var key="Hidden:"+room.id()+":"+p.getUUID();
        state.use(level,p,net.minecraft.world.InteractionHand.MAIN_HAND,hit);h.assertTrue(!r.state().events.getBoolean(key),"ordinary vision cannot open hidden cache");com.tnc.tnc.mana.sight.ManaSightServer.subscribe(p,true);for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));state.use(level,p,net.minecraft.world.InteractionHand.MAIN_HAND,hit);h.assertTrue(!r.state().events.getBoolean(key),"full bag retains claim");p.getInventory().setItem(0,ItemStack.EMPTY);p.getInventory().setItem(1,ItemStack.EMPTY);state.use(level,p,net.minecraft.world.InteractionHand.MAIN_HAND,hit);state.use(level,p,net.minecraft.world.InteractionHand.MAIN_HAND,hit);h.assertTrue(r.state().events.getBoolean(key)&&p.getInventory().countItem(AlchemyContent.POTIONS.get(Elixir.SPRING))==1&&p.getInventory().countItem(com.tnc.tnc.dungeon.DungeonRewards.material(r.theme))==2,"sight opens once with real rewards");r.closed=true;h.succeed();
    }
}
